actions.script:
if (ec.web.request.method != 'POST') {
    ec.web.response.setStatus(405); ec.web.response.setHeader('Allow','POST')
    ec.web.sendJsonResponse(groovy.json.JsonOutput.toJson([status:'error', message:'POST required'])); return
}
// Moqui has already read JSON bodies while building requestParameters; use the original bytes.
def rawBody = ec.web.getRequestBodyText() ?: ec.web.request.inputStream.getText('UTF-8')
def signature = ec.web.request.getHeader('X-Razorpay-Signature')
if (!rawBody || !signature) {
    ec.web.response.setStatus(400)
    ec.web.sendJsonResponse(groovy.json.JsonOutput.toJson([status:'error', message:'Body and signature required']))
    return
}
def body
try { body = new groovy.json.JsonSlurper().parseText(rawBody) }
catch (Exception e) {
    ec.web.response.setStatus(400); ec.web.sendJsonResponse(groovy.json.JsonOutput.toJson([status:'error', message:'Invalid payload'])); return
}
if (!(body instanceof Map)) {
    ec.web.response.setStatus(400); ec.web.sendJsonResponse(groovy.json.JsonOutput.toJson([status:'error', message:'Invalid payload'])); return
}
def result = ec.service.sync().name('zenith.saas.SaasPaymentServices.handle#RazorpayWebhook')
    .parameters([rawBody:rawBody, webhookSignature:signature]).disableAuthz().call()
if (!result?.accepted || ec.message.hasError()) {
    ec.web.response.setStatus(400); ec.web.sendJsonResponse(groovy.json.JsonOutput.toJson([status:'error', message:'Payment notification was not accepted'])); return
}
ec.web.sendJsonResponse([status:'ok'])
